import { MakeLogicType, connect, kea, path, selectors } from 'kea'

import { integrationsLogic } from 'lib/integrations/integrationsLogic'
import { teamLogic } from 'scenes/teamLogic'

import { IntegrationType, TeamPublicType, TeamType } from '~/types'

import { SendingDomain, sendingDomainOf } from './sendingDomain'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sendingDomainLogicValues {
    integrations: IntegrationType[] | null // integrationsLogic
    integrationsLoading: boolean // integrationsLogic
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    integrationsFailed: boolean
    sendingDomain: SendingDomain | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sendingDomainLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        integrationsFailed: (integrations: IntegrationType[] | null, integrationsLoading: boolean) => boolean
        sendingDomain: (
            integrations: IntegrationType[] | null,
            currentTeam: TeamPublicType | TeamType | null
        ) => SendingDomain | null
    }
}

export type sendingDomainLogicType = MakeLogicType<
    sendingDomainLogicValues,
    {},
    Record<string, any>,
    sendingDomainLogicMeta
>

export const sendingDomainLogic = kea<sendingDomainLogicType>([
    path(['products', 'workflows', 'frontend', 'Transactional', 'sendFromCode', 'sendingDomainLogic']),
    connect(() => ({
        values: [integrationsLogic, ['integrations', 'integrationsLoading'], teamLogic, ['currentTeam']],
    })),
    selectors({
        // integrationsLogic loads as it mounts, so no list and no request in flight means that load failed.
        integrationsFailed: [
            (s) => [s.integrations, s.integrationsLoading],
            (integrations: IntegrationType[] | null, integrationsLoading: boolean): boolean =>
                !integrationsLoading && integrations === null,
        ],
        sendingDomain: [
            (s) => [s.integrations, s.currentTeam],
            (
                integrations: IntegrationType[] | null,
                currentTeam: TeamType | TeamPublicType | null
            ): SendingDomain | null =>
                integrations
                    ? sendingDomainOf(
                          integrations,
                          currentTeam && 'workflows_config' in currentTeam
                              ? currentTeam.workflows_config?.default_email_integration_id
                              : null
                      )
                    : null,
        ],
    }),
])
